// Extract business requirements from Port.io webhook
const payload = $input.all()[0].json;

// Parse Port.io action data
const serviceData = {
  name: payload.inputs?.service_name || payload.entity?.properties?.service_name,
  type: payload.inputs?.service_type || payload.entity?.properties?.service_type,
  requirements: payload.inputs?.business_requirements || payload.entity?.properties?.business_requirements,
  team: payload.inputs?.team || payload.entity?.properties?.team,
  environment: payload.inputs?.environment || payload.entity?.properties?.environment || 'dev',
  entityId: payload.entity?.identifier,
  userId: payload.user?.email
};

// Validate required fields
if (!serviceData.name || !serviceData.type || !serviceData.requirements) {
  throw new Error('Missing required fields: name, type, or requirements');
}

// Generate repository name
serviceData.repoName = `msdp-${serviceData.name.toLowerCase().replace(/[^a-z0-9]/g, '-')}`;

// Set generation metadata
serviceData.generationId = `gen-${Date.now()}`;
serviceData.startTime = new Date().toISOString();

return { serviceData };

// Parse AI analysis response
const aiResponse = $input.all()[0].json.message.content;
const serviceData = $('Parse Service Request').item.json.serviceData;

let technicalSpec;
try {
  technicalSpec = JSON.parse(aiResponse);
} catch (e) {
  // Fallback if AI doesn't return valid JSON
  technicalSpec = {
    architecture: aiResponse,
    endpoints: [],
    database: {},
    dependencies: [],
    deployment: {},
    testing: {}
  };
}

// Generate service template based on type
const templates = {
  microservice: {
    framework: 'express',
    language: 'nodejs',
    database: 'postgresql',
    port: 3000 + Math.floor(Math.random() * 100)
  },
  frontend: {
    framework: 'nextjs',
    language: 'typescript',
    port: 4000 + Math.floor(Math.random() * 100)
  },
  mobile: {
    framework: 'react-native',
    language: 'typescript',
    platform: 'expo'
  },
  'shared-library': {
    framework: 'npm',
    language: 'typescript',
    type: 'library'
  }
};

const template = templates[serviceData.type] || templates.microservice;

// Combine everything
const enrichedService = {
  ...serviceData,
  technicalSpec,
  template,
  generatedCode: null
};

return { enrichedService };

