// Parse generated code and prepare for GitHub commits
const codeResponse = $('AI: Generate Code').item.json.message.content;
const serviceData = $('Process AI Analysis').item.json.enrichedService;

let generatedFiles;
try {
  generatedFiles = JSON.parse(codeResponse);
} catch (e) {
  // Fallback structure if AI doesn't return valid JSON
  generatedFiles = {
    'README.md': `# ${serviceData.name}\n\n${serviceData.requirements}`,
    'package.json': JSON.stringify({
      name: serviceData.repoName,
      version: '1.0.0',
      description: serviceData.requirements,
      main: 'index.js'
    }, null, 2)
  };
}

// Prepare commit data
const commits = [];
for (const [filePath, content] of Object.entries(generatedFiles)) {
  commits.push({
    path: filePath,
    content: typeof content === 'string' ? content : JSON.stringify(content, null, 2),
    message: `feat: Add ${filePath}`
  });
}

return { 
  commits,
  repoUrl: `https://github.com/msdp-platform/${serviceData.repoName}`,
  serviceData
};

